query GetContentBlockByLabel($label: String!) {
    content_blocks(
        filter: {
            block_label: {
                _eq: $label
            }
        }
        limit: 1
    ) {
        block_label
        block_content_html
    }
}

query GetEvents {
  outreach_events: events(
    filter: {
      status: { _eq: "published" }
      event_end_date: { _gte: "$NOW" }
      is_training: { _eq: false }
    }
    sort: ["event_start_date"]
  ) {
    ...eventFields
  }
  other_events: events(
    filter: {
      status: { _eq: "published" }
      event_end_date: { _gte: "$NOW" }
      is_training: { _eq: true }
    }
    sort: ["event_start_date"]
  ) {
    ...eventFields
  }
}

fragment eventFields on events {
  id
  title
  description
  location
  other_information
  contact
  event_start_date
  event_end_date
  time
  who_should_attend
  email
  is_training
}

