query GetMenuByLabel($menuLabel: String) {
    menus(filter: { 
      menu_label: { 
        _eq: $menuLabel 
      }
      menu: {
        _eq: "main"
      }
    }) {
        link_to_page {
            title
            url
        }
        menu_children {
            pages_id {
                title
                url
            }
        }
    }
}

query GetMenus($menu: String!) {
  menus(filter: { menu: { _eq: $menu } }) {
    id
    custom_url
    link_to_page {
      id
      slug
      url
    }
    menu
    menu_children {
      pages_id {
        id
        title
        url
      }
    }
    menu_icon
    menu_label
  }
}

query GetPageBySlug($slug: String) {
    page: pages(
        filter: {
            slug: {
                _eq: $slug
            }
        }
    ) {
        ...pageFields
    }
}

fragment pageFields on pages {
  id
  title
  slug
  template
  parent {
    title
    url
    parent {
      title
    }
  }
  hero_image {
    id
    description
  }
  hero_title
  related_content
  dataset_metadata {
    id
    name
    description
    update_frequency
    formats
    coverage_start
    coverage_end
    publisher
    related_links
    about
    preview_component
    terms {
      glossary_terms_id {
        id
        term
        definition
      }
    }
    charts(sort: ["sort"]) {
      ...chartCardFields
    }
  }
  page_blocks {
    id
    item {
      __typename
      ... on content_blocks {
        ...contentBlockFields
      }
      ... on tab_blocks {
        ...tabBlockFields
      }
      ... on card_blocks {
        ...cardBlockFields
      }
      ... on expansion_panels {
        ...expansionPanelBlockFields
      }
      ... on layout_column_blocks {
        ...layoutColumnBlockFields
      }
      ... on collection_blocks {
        ...collectionBlockFields
      }
      ... on chart_cards {
        ...chartCardFields
      }
    }
  }
  sidebar_blocks {
    id
    item {
      ... on content_blocks {
        ...contentBlockFields
        __typename
      }
      ... on collection_blocks {
        ...collectionBlockFields
        __typename
      }
    }
    __typename
  }
  meta_title
  meta_description
}

